command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="700500d92442f25002fb707031d7c2ff2cb2052f"
$branch="work/shell-provider-thumbnail-20261007"
Set-Location -LiteralPath $repo
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider thumbnail branch cleanup fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $main){throw "main moved before provider thumbnail branch cleanup"}
$remoteRef="refs/remotes/origin/"+$branch
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -ne 0){throw "provider thumbnail work branch is absent or unresolved"}
$branchHead=(& git rev-parse $remoteRef).Trim()
if($branchHead -ne $main){throw "provider thumbnail work branch does not point at accepted main"}
& git merge-base --is-ancestor $branchHead $observed
if($LASTEXITCODE -ne 0){throw "provider thumbnail work branch is not merged into main"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "provider thumbnail work branch deletion failed"}
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider thumbnail post-cleanup fetch failed"}
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -eq 0){throw "provider thumbnail work branch still exists after deletion"}
Write-Host "SHELL_PROVIDER_THUMBNAIL_WORK_BRANCH_CLEANUP=PASS"
